    canvas.width=Math.round(width*density);canvas.height=Math.round(height*density);
    const phone=width<700;
    root.classList.toggle('je-desk',!phone);
    const one=CFG.lines==1||CFG.lines==='1'||(CFG.lines!=2&&CFG.lines!=='2'&&!phone); root.classList.toggle('je-one',one);
    scale=Math.min(width*(phone?.86:.5)/724,height*(phone?.32:.36)/490,phone?1.05:1.2)*pct(CFG.sLogo,50,150);
    scale=Math.min(scale,width*.94/724);
    // the nimbu-mirchi hangs from the top centre; the emblem sits under it (a little above the middle), then the label and the moving line
    const charmH=CFG.nimbu===false?0:Math.round(Math.min(phone?260:300,height*(phone?.3:.32))*.5*pct(CFG.sNimbu,30,200));
    let tSize=(phone?Math.max(18,Math.min(28,width*.8/(12*.92))):Math.min(36,Math.max(28,scale*44)))*pct(CFG.sTitle,50,180);
    tSize=Math.round(Math.min(tSize,width*.9/((one?21:11)*.9)));
