    const top0=Math.max(charmH?charmH+12:8,Math.min(height*.5-245*scale-20,(height-block)/2-height*.04)+height*Math.max(-.2,Math.min(.2,(+CFG.pos||0)/100)));
    cy=Math.max(245*scale+8,top0+245*scale);
    titleEl.style.fontSize=tSize+'px';
    titleEl.style.top=Math.round(cy+245*scale+gap1)+'px';
    lineEl.style.fontSize=lSize+'px';lineBox.style.top=Math.round(cy+245*scale+gap1+tH+gap2)+'px';
